def _sanitize_validation_errors(exc: RequestValidationError) -> list[dict[str, object]]:
    """Drop submitted values from 422 bodies so PHI is not echoed."""
    sanitized: list[dict[str, object]] = []
    for error in exc.errors():
        sanitized.append(
            {
                "loc": error.get("loc"),
                "msg": error.get("msg"),
                "type": error.get("type"),
            }
        )
    return sanitized


def register_exception_handlers(app: FastAPI) -> None:
    @app.exception_handler(RequestValidationError)
    async def request_validation_error(
        _request: Request, exc: RequestValidationError
    ) -> JSONResponse:
        return JSONResponse(
            status_code=422,
            content={"detail": _sanitize_validation_errors(exc)},
        )

    @app.exception_handler(ClaimNotFoundError)

def test_validation_errors_do_not_echo_diagnosis_code(client: TestClient) -> None:
    """Malformed bodies must not echo sensitive fields such as diagnosis_code in 422 responses."""
    response = client.post(
        "/claims",
        json={
            "id": "bad-shape",
            "member_id": "m1",
            "submitted_at": "2026-03-20T10:00:00",
            "lines": [
                {
                    "line_number": 1,
                    "provider_id": "prov1",
                    "service_code": "PHYSIO-30",
                    "service_date": "2026-03-15",
                    "billed_amount_minor": "not-an-int",
                    "diagnosis_code": "SECRET-DX-99",
                }
            ],
        },
    )
    assert response.status_code == 422
    assert "SECRET-DX-99" not in response.text
    detail = response.json()["detail"]
    assert isinstance(detail, list)
    for item in detail:
        assert "input" not in item
        assert "SECRET-DX-99" not in str(item)


